-- OrganizationUnit
-- Tenant-owned internal subdivision of a specific real-world Organization, such as a department,
-- college/school, registrar office, division, or administrative unit. OrganizationIdentifier
-- identifies the institution to which the unit belongs; ParentOrganizationUnitIdentifier
-- optionally expresses hierarchy among units within that tenant and organization context.
CREATE TABLE core.organization_unit (
    tenant_identifier                                UUID NOT NULL,
    organization_unit_identifier                     TEXT NOT NULL,
    organization_identifier                          TEXT NOT NULL,
    parent_organization_unit_identifier              TEXT,
    organization_unit_code                           TEXT,
    organization_unit_name                           TEXT NOT NULL,
    organization_unit_type_identifier                TEXT,
    active_indicator                                 BOOLEAN NOT NULL,
    effective_start_date                             DATE,
    effective_end_date                               DATE,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_organization_unit PRIMARY KEY (tenant_identifier, organization_unit_identifier)
);
COMMENT ON TABLE core.organization_unit IS 'Tenant-owned internal subdivision of a specific real-world Organization, such as a department, college/school, registrar office, division, or administrative unit. OrganizationIdentifier identifies the institution to which the unit belongs; ParentOrganizationUnitIdentifier optionally expresses hierarchy among units within that tenant and organization context.';
COMMENT ON COLUMN core.organization_unit.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN core.organization_unit.organization_unit_identifier IS 'Unique identifier for the internal organization unit.';
COMMENT ON COLUMN core.organization_unit.organization_identifier IS 'Real-world organization within which this internal organization unit exists. Required because TenantIdentifier defines the data-ownership boundary, not the institution to which the unit belongs.';
COMMENT ON COLUMN core.organization_unit.parent_organization_unit_identifier IS 'Identifier for the immediate parent organization unit within the same TenantIdentifier and OrganizationIdentifier context.';
COMMENT ON COLUMN core.organization_unit.organization_unit_code IS 'Institutionally governed short code for the organization unit.';
COMMENT ON COLUMN core.organization_unit.organization_unit_name IS 'Human-readable name of the organization unit.';
COMMENT ON COLUMN core.organization_unit.organization_unit_type_identifier IS 'Identifier for the canonical type of internal organization unit.';
COMMENT ON COLUMN core.organization_unit.active_indicator IS 'Indicates whether the organization unit is active for current use.';
COMMENT ON COLUMN core.organization_unit.effective_start_date IS 'Date on which the organization unit became applicable or effective.';
COMMENT ON COLUMN core.organization_unit.effective_end_date IS 'Date on which the organization unit ceased to be applicable or effective.';
COMMENT ON COLUMN core.organization_unit.source_system_identifier IS 'Identifier for the source system from which the organization unit was imported or reconciled.';
COMMENT ON COLUMN core.organization_unit.source_system_key_value IS 'Source-system key value for the organization unit.';
COMMENT ON COLUMN core.organization_unit.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN core.organization_unit.created_date IS 'Date and time record was created';
COMMENT ON COLUMN core.organization_unit.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN core.organization_unit.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN core.organization_unit.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN core.organization_unit.deleted_date IS 'Date and time record was deleted';

