    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_source_system_lookup PRIMARY KEY (tenant_identifier, source_system_identifier)
);
COMMENT ON TABLE core.source_system_lookup IS 'A lookup table for tracking source systems providing data to the DHSS model objects.';
COMMENT ON COLUMN core.source_system_lookup.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN core.source_system_lookup.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN core.source_system_lookup.name IS 'A name for the record';
COMMENT ON COLUMN core.source_system_lookup.description IS 'A description for the record';
COMMENT ON COLUMN core.source_system_lookup.status IS 'Status of the lookup item (active, inactive)';
COMMENT ON COLUMN core.source_system_lookup.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN core.source_system_lookup.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN core.source_system_lookup.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN core.source_system_lookup.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN core.source_system_lookup.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN core.source_system_lookup.created_date IS 'Date and time record was created';
COMMENT ON COLUMN core.source_system_lookup.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN core.source_system_lookup.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN core.source_system_lookup.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN core.source_system_lookup.deleted_date IS 'Date and time record was deleted';

-- Template
-- A table containing templates to help with writing message content.
CREATE TABLE core.template (
    tenant_identifier                                UUID NOT NULL,
    template_identifier                              TEXT NOT NULL,
    information_source_organization_identifier       TEXT,
    source_system_identifier                         TEXT,
    name                                             TEXT,
    type                                             TEXT NOT NULL,
    text                                             TEXT NOT NULL,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_template PRIMARY KEY (tenant_identifier, template_identifier)
);
COMMENT ON TABLE core.template IS 'A table containing templates to help with writing message content.';
COMMENT ON COLUMN core.template.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN core.template.template_identifier IS 'Unique identifier for the template';
COMMENT ON COLUMN core.template.information_source_organization_identifier IS 'Organization identifier for the source of the information provided';
COMMENT ON COLUMN core.template.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN core.template.name IS 'A name for the record';
COMMENT ON COLUMN core.template.type IS 'Indicates the type or purpose of the template';
COMMENT ON COLUMN core.template.text IS 'The text of the template';
COMMENT ON COLUMN core.template.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN core.template.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN core.template.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN core.template.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN core.template.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN core.template.created_date IS 'Date and time record was created';
COMMENT ON COLUMN core.template.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN core.template.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN core.template.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN core.template.deleted_date IS 'Date and time record was deleted';

-- Tenant
-- Defines the tenant data-ownership and security boundary for a GUIDE deployment. TenantIdentifier
-- is a UUID and is distinct from any real-world OrganizationIdentifier represented within the
-- tenant.
CREATE TABLE core.tenant (
    tenant_identifier                                UUID NOT NULL,
    tenant_name                                      TEXT NOT NULL,
    active_indicator                                 BOOLEAN NOT NULL DEFAULT TRUE,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_tenant PRIMARY KEY (tenant_identifier)
);
COMMENT ON TABLE core.tenant IS 'Defines the tenant data-ownership and security boundary for a GUIDE deployment. TenantIdentifier is a UUID and is distinct from any real-world OrganizationIdentifier represented within the tenant.';
COMMENT ON COLUMN core.tenant.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN core.tenant.tenant_name IS 'Human-readable name of the tenant context.';
COMMENT ON COLUMN core.tenant.active_indicator IS 'Indicates whether the tenant context is active.';
COMMENT ON COLUMN core.tenant.created_date IS 'Date and time the tenant record was created.';
COMMENT ON COLUMN core.tenant.updated_date IS 'Date and time the tenant record was last updated.';

-- TenantOrganizationRole
-- Effective-dated tenant-relative role played by an organization, such as HomeInstitution.
-- Prevents contextual roles from becoming intrinsic organization attributes.
CREATE TABLE core.tenant_organization_role (
    tenant_identifier                                UUID NOT NULL,
    tenant_organization_role_identifier              TEXT NOT NULL,
    organization_identifier                          TEXT NOT NULL,
    tenant_organization_role_type_identifier         TEXT NOT NULL,
    effective_start_date                             DATE,
    effective_end_date                               DATE,
    CONSTRAINT pk_tenant_organization_role PRIMARY KEY (tenant_identifier, tenant_organization_role_identifier)
);
COMMENT ON TABLE core.tenant_organization_role IS 'Effective-dated tenant-relative role played by an organization, such as HomeInstitution. Prevents contextual roles from becoming intrinsic organization attributes.';
COMMENT ON COLUMN core.tenant_organization_role.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN core.tenant_organization_role.tenant_organization_role_identifier IS 'Unique identifier for a tenant-relative organization role.';
COMMENT ON COLUMN core.tenant_organization_role.organization_identifier IS 'Organization playing the role in this tenant context.';
COMMENT ON COLUMN core.tenant_organization_role.tenant_organization_role_type_identifier IS 'Governed tenant-relative role such as HomeInstitution.';
COMMENT ON COLUMN core.tenant_organization_role.effective_start_date IS 'Date on which the tenant-relative role becomes effective.';
COMMENT ON COLUMN core.tenant_organization_role.effective_end_date IS 'Date after which the tenant-relative role is no longer effective.';
